import functools

def memoize(func):
    cache = {}

    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]

    wrapper.cache = cache
    return wrapper

tests.source:
def test_caches_repeated_calls(self):
    calls = []

    @memoize
    def square(x):
        calls.append(x)
        return x * x

    self.assertEqual(square(3), 9)
    self.assertEqual(square(3), 9)
    self.assertEqual(calls, [3])

def test_different_arguments_are_cached_separately(self):
    @memoize
    def double(x):
        return x * 2

    self.assertEqual(double(2), 4)
    self.assertEqual(double(5), 10)
    self.assertEqual(len(double.cache), 2)

def test_exposes_cache_attribute(self):
    @memoize
    def identity(x):
        return x

    identity(7)
    self.assertEqual(identity.cache[(7,)], 7)

